373	// ParseWithStatus parses without a cancellation deadline of its own. It is the
374	// entry point for callers that have no context to stop it.
375	func (TreeSitterParser) ParseWithStatus(path, content string) ([]Entity, string, ParseStatus) {
376		return TreeSitterParser{}.ParseWithStatusCtx(context.Background(), path, content)
377	}
378	
379	// ctxStop returns a cheap "has this context finished?" predicate, or nil when
380	// the context can never finish. A nil predicate is what the unbudgeted path
381	// gets: the walk then carries no per-node check at all, so a build with no
382	// deadline does exactly the work — and produces exactly the bytes — it did
383	// before deadlines existed.
384	func ctxStop(ctx context.Context) func() bool {
385		done := ctx.Done()
386		if done == nil {
387			return nil
388		}
389		return func() bool {
390			select {
391			case <-done:
392				return true
393			default:
394				return false
395			}
396		}
397	}
398	
399	// stopped reports whether a stop predicate exists and has fired. A nil
400	// predicate is the unbudgeted path and always answers false, so every guard
401	// built on this is inert -- not merely cheap -- when the caller set no deadline.
402	func stopped(stop func() bool) bool {
403		return stop != nil && stop()
404	}
405	
406	// parseStoppedStatus describes a parse abandoned because the caller's budget
407	// expired. It reuses the E_PARSE_TIMEOUT code that a tree-sitter parse stopped
408	// by the same context already reports; the detail says which half stopped.
409	func parseStoppedStatus(ctx context.Context, where string) ParseStatus {
410		return ParseStatus{
411			ParseError: true,
412			Code:       "E_PARSE_TIMEOUT",
413			Detail:     fmt.Sprintf("%s stopped by caller: %v", where, ctx.Err()),
414		}
415	}
416	
417	// ParseWithStatusCtx is ParseWithStatus under a caller deadline. Both halves of
418	// the per-file cost observe ctx: the tree-sitter parse (whose 5s internal cap is
419	// now derived from ctx rather than from context.Background, so an expiring budget
420	// sets the C parser's cancellation flag) and the entity walk, which is the far
421	// larger term — it is superlinear in nesting depth and, before ctx reached it,
422	// could run for minutes on one pathological file with nothing able to stop it.
423	func (TreeSitterParser) ParseWithStatusCtx(ctx context.Context, path, content string) ([]Entity, string, ParseStatus) {
424		spec, ok := languageForContent(path, content)
425		if !ok {
426			return nil, "", ParseStatus{}
427		}
428		if spec.language == "Kustomize" && looksLikeFluxKustomizationManifest(content) {
429			spec = treeSitterLanguages[".yaml"]
430		}
431		if strings.EqualFold(filepath.Ext(path), ".h") && looksLikeObjectiveC(content) {
432			// Objective-C classes are canonically anchored at their .h header
433			// (`@interface Foo : NSObject` lives there; the .m holds the
434			// @implementation), so sniffed headers parse with the vendored
435			// tree-sitter-objc grammar like .m files instead of falling back to
436			// inventory. Headers that don't sniff keep the C/C++ routing below.
437			spec = treeSitterLanguages[".m"]
438		} else if strings.EqualFold(filepath.Ext(path), ".h") && looksLikeCPlusPlusHeader(content) {
439			spec = treeSitterLanguages[".hpp"]
440		}
441		flowJS := false
442		if spec.language == "JavaScript" && looksLikeFlowJavaScript(content) {
443			// Flow-typed JavaScript parses with the vendored TSX grammar (a
444			// near-superset of Flow's annotation syntax) plus a small
445			// position-preserving mask; tree-sitter-javascript chokes on every
446			// type annotation. The language label stays "JavaScript", mirroring
447			// the .jsx routing. See flowjs.go for the probe evidence.
448			spec.grammar = treesittertsx.GetLanguage()
449			flowJS = true
450		}
451		if spec.language == "SQL" {
452			spec.grammar = pgsql.GetLanguage()
453		}
454		// The stop predicate is built HERE, above the three return paths that never
455		// reach tree-sitter, not below them: the dedicated Groovy parser, every
456		// grammar-less fallback parser and YAML's entity extraction each returned
457		// straight out of this function with nothing able to stop them, so a budget
458		// that expired inside one of them waited for the whole file -- and
459		// processProviderFile discards that file anyway once ctx has expired, so all
460		// of it was overshoot spent on a result nobody keeps. stop is nil whenever
461		// the caller set no deadline, so the unbudgeted path carries no check at all.
462		stop := ctxStop(ctx)
463		if spec.language == "Groovy" {
464			// Groovy uses a dedicated structural parser (see groovy.go): the best
465			// available tree-sitter-groovy grammar fails on fundamental syntax —
466			// quoted method names, casts, slashy strings — leaving 1,400+ parse
467			// errors on real repos, so it is not consulted at all.
468			//
469			// It is also superlinear: every entity's body hash joins the lines it
470			// spans, and nested classes each span the rest of the file, so one
471			// 12k-class file cost 21.0s against a 500ms budget. The scanner takes
472			// the predicate; this checks the outcome, so a scan cut short is a
473			// dropped file rather than a silently short symbol list.
474			if stopped(stop) {
475				return nil, spec.language, parseStoppedStatus(ctx, "groovy parse")
476			}
477			entities, status := groovyEntities(content, stop)
478			if stopped(stop) {
479				return nil, spec.language, parseStoppedStatus(ctx, "groovy parse")
480			}
481			return entities, spec.language, status
482		}
483		if spec.grammar == nil {
484			// Every grammar-less fallback (Dockerfile, JSON, TOML, XML, Make,
485			// Markdown, HTML, CSS, GraphQL, Vue/Svelte and the inventory default)
486			// is a single linear pass, so the residual here is bounded by the
487			// file-size cap rather than superlinear -- but it observed nothing at
488			// all, and the file is discarded on expiry regardless.
489			if stopped(stop) {
490				return nil, spec.language, parseStoppedStatus(ctx, "fallback parse")
491			}
492			entities := fallbackEntities(path, content, spec.language, stop)
493			if stopped(stop) {
494				return nil, spec.language, parseStoppedStatus(ctx, "fallback parse")
495			}
496			return entities, spec.language, ParseStatus{}
497		}
498		// Source masking is language-specific work in its own right, and it sat
499		// between the predicate above and the budgeted parse context below, so
500		// nothing observed the budget across it. Rust's mask is the extreme case:
501		// it runs up to eight tree-sitter unwrap passes of its own. Guard the
502		// stage on entry and hand the mask the context, so no later stage can be
503		// reached unbudgeted.
504		if stopped(stop) {
505			return nil, spec.language, parseStoppedStatus(ctx, "source masking")
506		}
507		src := []byte(content)
508		parseSrc := src
509		entitySrc := src
510		entityLineOffset := 0
511		if spec.language == "Protocol Buffers" {
512			prepared, original, lineOffset := prepareProtocolBuffersParseSource(content)
513			parseSrc = []byte(prepared)
514			entitySrc = []byte(original)
515			entityLineOffset = lineOffset
516		}
517		if spec.language == "SQL" {
518			parseSrc = []byte(maskPostgresUnsupportedSyntax(ctx, content))
519		}
520		if spec.language == "C" {
521			parseSrc = []byte(maskCUnsupportedSyntax(content))
522		}
523		if spec.language == "Objective-C" {
524			parseSrc = []byte(maskObjectiveCUnsupportedSyntax(content))
525		}
526		if spec.language == "Bash" {
527			parseSrc = []byte(maskBashUnsupportedSyntax(content))
528		}
529		if spec.language == "Zsh" {
530			parseSrc = []byte(maskZshUnsupportedSyntax(content))
531		}
532		if spec.language == "Java" {
533			parseSrc = []byte(maskJavaUnsupportedSyntax(content))
534		}
535		if spec.language == "C#" {
536			parseSrc = []byte(maskCSharpUnsupportedSyntax(content))
537		}
538		if spec.language == "C++" {
539			parseSrc = []byte(maskCPlusPlusUnsupportedSyntax(content))
540		}
541		if spec.language == "Kotlin" {
542			parseSrc = []byte(maskKotlinUnsupportedSyntax(path, content))
543		}
544		if spec.language == "Swift" {
545			parseSrc = []byte(maskSwiftUnsupportedSyntax(content))
546		}
547		if spec.language == "Dart" {
548			parseSrc = []byte(maskDartUnsupportedSyntax(content))
549		}
550		if spec.language == "OCaml" && strings.EqualFold(filepath.Ext(path), ".mli") {
551			parseSrc = []byte(maskOCamlInterfaceSyntax(content))
552		}
553		if spec.language == "F#" {
554			parseSrc = []byte(maskFSharpUnsupportedSyntax(content))
555		}
556		if spec.language == "YAML" {
557			parseSrc = []byte(maskYAMLUnsupportedSyntax(content))
558		}
559		if spec.language == "TypeScript" {
560			if strings.EqualFold(filepath.Ext(path), ".tsx") {
561				parseSrc = []byte(maskTSXUnsupportedSyntax(content))
562			} else {
563				parseSrc = []byte(maskTypeScriptUnsupportedSyntax(content))
564			}
565		}
566		if spec.language == "Rust" {
567			parseSrc = []byte(maskRustUnsupportedSyntax(ctx, content))
568		}
569		if flowJS {
570			parseSrc = []byte(maskFlowJavaScriptUnsupportedSyntax(content))
571		}
572		if stopped(stop) {
573			return nil, spec.language, parseStoppedStatus(ctx, "source masking")
574		}
575		parseCtx, cancel := context.WithTimeout(ctx, treeSitterParseTimeout)
576		defer cancel()
577		// Own the parser and tree explicitly and free their native (cgo) memory on
578		// return. sitter.ParseCtx leaves the C parser and tree to be reclaimed by Go
579		// finalizers, but the Go heap stays small while parsing, so GC — and thus those
580		// finalizers — runs only every couple of minutes. Re-parse-heavy passes on large
581		// repos then pile up thousands of tree-sitter trees off-heap (12+ GB RSS on
582		// microsoft/TypeScript) even though the live Go heap is well under 1 GB.
583		parser := sitter.NewParser()
584		defer parser.Close()
585		parser.SetLanguage(spec.grammar)
586		tree, err := parser.ParseCtx(parseCtx, nil, parseSrc)
587		if tree != nil {
588			defer tree.Close()
589		}
590		var root *sitter.Node
591		if tree != nil {
592			root = tree.RootNode()
593		}
594		if err != nil || root == nil || root.IsNull() {
595			detail := "tree-sitter parse failed"
596			code := "E_PARSE_ERROR"
597			if err != nil {
598				detail = err.Error()
599				if parseCtx.Err() != nil {
600					code = "E_PARSE_TIMEOUT"
601					detail = fmt.Sprintf("tree-sitter parse exceeded %s", treeSitterParseTimeout)
602					if ctx.Err() != nil {
603						// The caller's budget stopped the parse, not the 5s cap.
604						detail = fmt.Sprintf("tree-sitter parse stopped by caller: %v", ctx.Err())
605					}
606				}
607			}
608			return nil, spec.language, ParseStatus{ParseError: true, Code: code, Detail: detail}
609		}
610		if spec.language == "YAML" {
611			// YAML's entities come from its own line scanner, not from the walk, so
612			// the walk's predicate never covered it either.
613			if stopped(stop) {
614				return nil, spec.language, parseStoppedStatus(ctx, "yaml entity extraction")
615			}
616			status := ParseStatus{}
617			if root.HasError() {
618				status = ParseStatus{ParseError: true, Code: "E_PARSE_ERROR", Detail: parseErrorDetail(root, src)}
619			}
620			return yamlEntities(path, content, stop), spec.language, status
621		}
622	
623		var entities []Entity
624		depthExceeded := walkEntities(ctx, root, entitySrc, spec.language, "", stop, &entities)
625		// walkEntities returns early when the budget expires, but everything below
626		// it -- the language-specific supplemental extractors, the binding collapse,
627		// the offset fixup and the final sort -- used to run regardless, and one of
628		// those passes is superlinear in match count. processProviderFile then drops
629		// the whole file because ctx expired, so every bit of it was overshoot spent
630		// on a result nobody keeps. Bail out at each pass boundary instead. stop is
631		// nil whenever the caller has no deadline, so an unbudgeted parse does
632		// exactly the work, and emits exactly the bytes, it did before.
633		if stopped(stop) {
634			return nil, spec.language, parseStoppedStatus(ctx, "entity walk")
635		}
636		if spec.language == "C++" {
637			entities = appendMissingEntities(entities, cPlusPlusTypeAliasEntities(content)...)
638		}
639		if stopped(stop) {
640			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
641		}
642		if spec.language == "C" || spec.language == "C++" {
643			// The C mask blanks `#define` lines before tree-sitter, so macro names (opcodes,
644			// X-macros like MP_BC_*) never become symbols and a graph lookup for them returns
645			// nothing. Recover them from the UNMASKED content so `symbols`/`def <MACRO>` resolve.
646			entities = appendMissingEntities(entities, cMacroEntities(content)...)
647		}
648		if stopped(stop) {
649			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
650		}
651		if spec.language == "Kotlin" {
652			entities = append(entities, kotlinPrimaryConstructorFieldEntities(content)...)
653		}
654		if stopped(stop) {
655			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
656		}
657		if spec.language == "JavaScript" || spec.language == "TypeScript" {
658			entities = appendMissingEntities(entities, javascriptExportedVariableEntities(content, stop)...)
659			entities = appendMissingEntities(entities, javascriptAssignmentMethodEntities(content)...)
660			entities = appendMissingEntities(entities, javascriptDefaultExportEntities(path, content)...)
661			entities = append(entities, graphqlResolverEntities(path, content)...)
662		}
663		if stopped(stop) {
664			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
665		}
666		if spec.language == "SQL" {
667			// Run the regex fallback extractors on comment-stripped source so that
668			// commented-out (or otherwise non-DDL) text is not picked up as a phantom
669			// entity. The tree-sitter walk above already used masked source.
670			regexSrc := []byte(stripSQLComments(string(src)))
671			entities = append(entities, postgresFunctionEntities(regexSrc)...)
672			entities = append(entities, postgresPolicyEntities(regexSrc)...)
673		}
674		if stopped(stop) {
675			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
676		}
677		if spec.language == "Lua" {
678			// tree-sitter-lua can recover from large annotated files with incomplete
679			// top-level function coverage. Supplement it with the canonical Lua
680			// declaration forms so exported table functions stay discoverable.
681			entities = appendMissingEntities(entities, luaFunctionEntities(content)...)
682		}
683		if stopped(stop) {
684			return nil, spec.language, parseStoppedStatus(ctx, "supplemental entity recovery")
685		}
686		if spec.language == "Objective-C" {
687			// Large Objective-C implementation files with blocks/macros can leave
688			// recoverable method definitions out of the tree-sitter walk. Supplement
689			// only brace-backed implementation methods; header prototypes end in ';'.
690			entities = appendMissingEntities(entities, objectiveCMethodEntities(content)...)
691		}
692		if stopped(stop) {
693			return nil, spec.language, parseStoppedStatus(ctx, "entity reconciliation")
694		}
695		// A name binding and the function expression that initialises it are ONE entity. The
696		// tree-sitter walk classifies such a declarator by its VALUE while the regex recovery
697		// passes above classify it by its DECLARATOR, so both can emit a record with the same
698		// qualified name for the same source location. Collapse them onto the function record
699		// (real span, real signature) LAST, after every pass has contributed.
700		entities = collapseFunctionValueBindings(entities)
701		if stopped(stop) {
702			return nil, spec.language, parseStoppedStatus(ctx, "entity reconciliation")
703		}
704		if entityLineOffset > 0 {
705			for index := range entities {
706				entities[index].StartLine -= entityLineOffset
707				entities[index].EndLine -= entityLineOffset
708				if entities[index].nameLine > 0 {
709					entities[index].nameLine -= entityLineOffset
710				}
711				// prepareProtocolBuffersParseSource prepends one synthetic syntax
712				// declaration to both parser and entity views. Byte metadata must point
713				// back into the authored content just like the adjusted line metadata.
714				entities[index].sourceStartByte -= len(protobufSyntheticSyntax)
715				entities[index].sourceEndByte -= len(protobufSyntheticSyntax)
716				if entities[index].sourceStartByte < 0 || entities[index].sourceEndByte <= entities[index].sourceStartByte {
717					entities[index].sourceStartByte = 0
718					entities[index].sourceEndByte = 0
719				}
720			}
721		}
722		if stopped(stop) {
723			return nil, spec.language, parseStoppedStatus(ctx, "entity sort")
724		}
725		sort.Slice(entities, func(i, j int) bool {
726			if entities[i].StartLine == entities[j].StartLine {
727				return entities[i].Name < entities[j].Name
728			}
729			return entities[i].StartLine < entities[j].StartLine
730		})
731		status := ParseStatus{}
732		switch {
733		case depthExceeded && root.HasError():
734			// BOTH too deep and malformed. Truncation alone is a partial result,
735			// but a malformed tree is not: the entities recovered from it may be
736			// wrong, not merely fewer, so the caller must be free to suppress the
737			// file rather than diff against them. Error therefore dominates depth —
738			// Partial stays false, and a zero-entity side goes back down
739			// analyze.go's total-failure path instead of emitting every symbol on
740			// the other side as a phantom removal. Both conditions are named in the
741			// detail so the operator is not left guessing which one to fix; the
742			// error-detail walk is safe to run here because it is itself bounded.
743			status = ParseStatus{
744				ParseError:    true,
745				DepthExceeded: true,
746				Code:          "E_PARSE_ERROR",
747				Detail: fmt.Sprintf("%s; AST nesting also exceeded the %d-level walk limit, so declarations nested deeper than that were not extracted",
748					parseErrorDetailWithLineOffset(root, entitySrc, entityLineOffset), maxParseWalkDepth),
749			}
750		case depthExceeded:
751			// A truncated walk on a tree that PARSED CLEANLY (the case above takes
752			// the malformed one): truncation is why declarations are missing, and it
753			// is the actionable one, so it wins the single status slot. The
754			// error-detail walk is skipped with it: there is no error to report.
755			//
756			// Partial, not total: the entities above the limit were extracted from a
757			// tree that parsed, so they are real. Consumers must degrade rather than
758			// discard — the diff keeps this file's delta (analyze.go) — while still
759			// counting the file as an incompletely understood one (provider.go).
760			status = ParseStatus{
761				ParseError:    true,
762				Partial:       true,
763				DepthExceeded: true,
764				Code:          "E_PARSE_DEPTH_EXCEEDED",
765				Detail:        fmt.Sprintf("AST nesting exceeded the %d-level walk limit; declarations nested deeper than that were not extracted", maxParseWalkDepth),
766			}
767		case root.HasError():
768			status = ParseStatus{ParseError: true, Code: "E_PARSE_ERROR", Detail: parseErrorDetailWithLineOffset(root, entitySrc, entityLineOffset)}
769			// Every consumer turns this status into its diagnostic, so deciding the
770			// grammar gap here is what lets all of them inherit it. A Go file that
771			// go/parser accepts is valid Go: the error nodes are the grammar's, not
772			// the file's.
773			if spec.language == "Go" {
774				if stopped(stop) {
775					return nil, spec.language, parseStoppedStatus(ctx, "go syntax check")
776				}
777				if file, valid := goReferenceParse(src); valid {
778					if lost := goDeclarationsLost(file, entities); len(lost) > 0 {
779						// Valid Go, but the recovery dropped declarations: symbols
780						// are known to be missing, so this stays a counted
781						// E_PARSE_ERROR rather than a grammar-gap warning.
782						status.Detail += goDeclarationsLostDetail(lost)
783					} else {
784						status = ParseStatus{
785							ParseError: true,
786							GrammarGap: true,
787							Code:       GoGrammarGapCode,
788							Detail:     status.Detail + "; go/parser accepts the file",
789						}
790					}
791				}
792			}
793		}
794		return entities, spec.language, status
795	}
