5501		var fsharpProjectDeclaredModulePaths map[string]bool
5502		if needsCallScan {
5503			fsharpProjectModulePathBySymbolID, fsharpProjectDeclaredModulePaths = fsharpProjectModulePaths(files, recordsByFile, readContent)
5504		}
5505	
5506		// The file scan. Every index built above is read-only from here on, and the
5507		// four accumulators it feeds are append-only, so files resolve on workers
5508		// while a reducer replays each file's relations, failures and accumulator
5509		// entries in the original file order. The reducer decides emission order, so
5510		// worker timing cannot reach the snapshot bytes.
5511		resolveFileRelations := func(workerCtx context.Context, file FileRecord, emit func(RelationRecord)) fileRelationScan {
5512			var result fileRelationScan
5513			// Relations stream through a bounded channel to the ordered reducer.
5514			// Failures remain per-file metadata, replayed after that file's relations.
5515			var bufferFailure func(PartialFailure)
5516			if recordFailure != nil {
5517				bufferFailure = func(failure PartialFailure) { result.failures = append(result.failures, failure) }
5518			}
5519			recordFailure := bufferFailure
5520			// The outer shouldStop reads emitErr, which the reducer writes. A worker
5521			// has to ask the context instead.
5522			shouldStop := func() bool { return workerCtx.Err() != nil }
5523			if shouldStop() {
5524				return result
5525			}
5526			imports, havePrecomputedImports := precomputedImports[file.Path]
5527			content := ""
5528			if !havePrecomputedImports || !skipFastProfilePerSymbolScan(spec, file.Language) {
5529				var ok bool
5530				content, ok = readContent(file.Path)
5531				if !ok {
5532					return result
5533				}
5534				if !havePrecomputedImports {
5535					imports = importsFor(file.Path, content)
5536				}
5537			}
5538			fromID := fileID(repoKey, file.Path)
5539			for _, imported := range imports {
5540				if resolved, ok := resolveLocalImport(file.Path, imported, knownFiles); ok {
5541					emit(RelationRecord{
5542						RecordType:    "relation",
5543						FromID:        fromID,
5544						ToID:          fileID(repoKey, resolved),
5545						Type:          "IMPORTS",
5546						Confidence:    0.95,
5547						Reason:        "relative import resolved to local file",
5548						RelationScope: "module",
5549						Resolution:    "import_resolved",
5550						TargetKind:    "file",
5551						Evidence: []Evidence{{
5552							Kind:     "import_statement",
5553							FilePath: file.Path,
5554							Detail:   imported,
5555						}},
5556						WarningCodes: []string{},
5557					})
5558					continue
5559				}
5560				if resolved, ok := manifestImports.resolve(file.Path, imported); ok {
5561					emit(RelationRecord{
5562						RecordType:    "relation",
5563						FromID:        fromID,
5564						ToID:          fileID(repoKey, resolved.Path),
5565						Type:          "IMPORTS",
5566						Confidence:    resolved.Confidence,
5567						Reason:        resolved.Reason,
5568						RelationScope: resolved.Scope,
5569						Resolution:    "import_resolved",
5570						TargetKind:    "file",
5571						Evidence: []Evidence{{

